// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

interface IERC20 {
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
}

library SafeERC20 {
    function safeTransferFrom(
        IERC20 token,
        address from,
        address to,
        uint256 value
    ) internal {
        require(address(token).code.length > 0, "SafeERC20: call to non-contract");
        require(to != address(0), "SafeERC20: transfer to zero address");
        require(from != address(0), "SafeERC20: transfer from zero address");
        
        (bool success, bytes memory returndata) = address(token).call(
            abi.encodeWithSelector(token.transferFrom.selector, from, to, value)
        );
        require(success && (returndata.length == 0 || abi.decode(returndata, (bool))), 
            "SafeERC20: transfer failed"
        );
    }
}

contract MultiSender {
    using SafeERC20 for IERC20;
    
    uint256 public constant BATCH_SIZE = 250;
    
    event BatchProcessed(address indexed token, uint256 processed);
    event TransferFailed(address indexed token, address recipient, uint256 amount);
    
    uint256 private _locked = 1;
    modifier nonReentrant() {
        require(_locked == 1, "Reentrant call");
        _locked = 2;
        _;
        _locked = 1;
    }
    
    function _validateInputs(
        IERC20[] calldata tokens,
        address[] calldata recipients,
        uint256[][] calldata amounts,
        uint256 batchSize
    ) private view {
        require(tokens.length > 0, "No tokens provided");
        require(recipients.length > 0, "Empty recipients array");
        require(batchSize > 0 && batchSize <= BATCH_SIZE, "Invalid batch size");
        
        for(uint256 i = 0; i < tokens.length; i++) {
            require(address(tokens[i]) != address(0), "Invalid token address");
            require(amounts[i].length == recipients.length, "Length mismatch");
            
            uint256 totalAmount;
            for(uint256 j = 0; j < amounts[i].length; j++) {
                require(amounts[i][j] > 0, "Zero amount transfer");
                require(recipients[j] != address(0), "Invalid recipient");
                require(recipients[j] != address(this), "Cannot send to contract");
                totalAmount += amounts[i][j];
            }
            
            require(tokens[i].balanceOf(msg.sender) >= totalAmount, "Insufficient balance");
            require(tokens[i].allowance(msg.sender, address(this)) >= totalAmount, "Insufficient allowance");
        }
    }
    
    function _processSingleTransfer(
        IERC20 token,
        address recipient,
        uint256 amount,
        uint256 start,
        uint256 current,
        address[] calldata recipients
    ) private returns (bool) {
        if(current > start) {
            for(uint256 i = start; i < current; i++) {
                if(recipients[i] == recipient) {
                    emit TransferFailed(address(token), recipient, amount);
                    return false;
                }
            }
        }
        
        token.safeTransferFrom(msg.sender, recipient, amount);
        return true;
    }
    
    function _processTokenBatch(
        IERC20 token,
        address[] calldata recipients,
        uint256[] calldata amounts,
        uint256 start,
        uint256 end
    ) private returns (uint256) {
        uint256 successful;
        
        for(uint256 j = start; j < end; j++) {
            if(_processSingleTransfer(token, recipients[j], amounts[j], start, j, recipients)) {
                successful++;
            }
        }
        
        emit BatchProcessed(address(token), end);
        return successful;
    }
    
    function multiSendTokens(
        IERC20[] calldata tokens,
        address[] calldata recipients,
        uint256[][] calldata amounts,
        uint256 batchSize
    ) external nonReentrant {
        _validateInputs(tokens, recipients, amounts, batchSize);
        
        for(uint256 i = 0; i < tokens.length; i++) {
            uint256 successfulTransfers;
            uint256 numBatches = (recipients.length + batchSize - 1) / batchSize;
            
            for(uint256 batch = 0; batch < numBatches; batch++) {
                uint256 start = batch * batchSize;
                uint256 end = start + batchSize;
                if(end > recipients.length) {
                    end = recipients.length;
                }
                
                successfulTransfers += _processTokenBatch(
                    tokens[i],
                    recipients,
                    amounts[i],
                    start,
                    end
                );
            }
            
            require(successfulTransfers > 0, "No successful transfers for token");
        }
    }
}
